// A shared orientation for the paragraph desk and the source finder.
// Every prose block is labelled by role; planning prompts never become a draft.
export function argumentFlowHTML(c, esc, {revision=false}={}) {
 const n=c.current,link=id=>`#${revision?'revision':'paper'}/${encodeURIComponent(id)}`;
 const point=(item,position)=>item?`<article class="argument-move ${position==='Here'?'current':''}"><small>${esc(position)} · ${esc(item.id)}</small><h3>${position==='Here'?esc(item.title):`<a href="${link(item.id)}">${esc(item.title)}</a>`}</h3><p><strong>${esc(item.purpose)}</strong></p>${item.plan.contribution?`<p><small>Your saved intended point</small><br>${esc(item.plan.contribution)}</p>`:`<p>${esc(item.ideas[0]||'')}</p>`}${item.selected_text?`<details><summary>Read the text selected for ${esc(item.id)}</summary><p class="text-role source">Selected manuscript version · read only here</p><div class="argument-selected">${esc(item.selected_text)}</div></details>`:'<p class="tiny">No manuscript version selected yet. This is the intended role.</p>'}</article>`:`<article class="argument-move"><small>${esc(position)}</small><p>${position==='Before'?'Start the argument here.':'Close the argument within the evidence presented.'}</p></article>`;
 const specific=n.id==='I-06'?'<p class="argument-explanation"><strong>In plain language:</strong> bring the earlier limitations together. Explain why deciding what counts as expected execution and deciding what deserves business review belong to one connected design problem. This gives the next move a reason to introduce WISE. Do not just list two gaps or describe every method step here.</p>':'';
 const unresolved=c.directions.filter(d=>d.status!=='confirmed'),confirmed=c.directions.filter(d=>d.status==='confirmed');
 const directions=items=>items.map(d=>`<p><strong>${esc(d.status==='confirmed'?'Confirmed by you':d.status==='needs_clarification'?'Unresolved question':'Proposed · not yet confirmed')}</strong><br>${esc(d.text)}${d.document_id?`<br><a href="#revision/${n.id}?document=${encodeURIComponent(d.document_id)}&segment=${encodeURIComponent(d.segment_id)}">Read discussion source</a>`:''}</p>`).join('');
 return `<section class="argument-orientation" aria-label="Argument flow for ${esc(n.id)}"><p class="eyebrow">1 · Understand this argument move</p><div class="section-row"><h2>What should ${esc(n.id)} do here?</h2><a class="btn quiet" href="#paper/flow-${esc(n.id)}">See the whole argument ↗</a></div><p class="tiny">Planning guidance · ${esc(c.section)}. Arrows show reading order.</p><div class="argument-flow">${point(c.before,'Before')}<span class="argument-arrow" aria-hidden="true">→</span>${point(n,'Here')}<span class="argument-arrow" aria-hidden="true">→</span>${point(c.after,'Next')}</div>${specific}<details class="argument-details" ${n.id==='I-06'?'':'open'}><summary>What this move needs to establish</summary><ol>${n.ideas.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p><strong>Boundary:</strong> ${esc(n.boundary)}</p>${n.plan.bridge?`<p><strong>Your connecting reason:</strong> ${esc(n.plan.bridge)}</p>`:''}${n.plan.handover?`<p><strong>Your planned handover:</strong> ${esc(n.plan.handover)}</p>`:''}</details>${confirmed.length?`<details open class="argument-directions"><summary>Confirmed directions (${confirmed.length})</summary>${directions(confirmed)}</details>`:''}${unresolved.length?`<details class="argument-directions unresolved"><summary>${unresolved.length} discussion directions still need review</summary><p class="tiny">The older overview is provisional where these directions differ. Do not treat unresolved choices as settled.</p>${directions(unresolved)}</details>`:''}<details class="argument-details"><summary>See the whole ${esc(c.section.toLowerCase())} argument</summary><nav class="argument-sequence" aria-label="Section argument sequence">${c.sequence.map(s=>`<a href="${link(s.id)}" ${s.id===n.id?'aria-current="step"':''}><small>${esc(s.id)}</small><strong>${esc(s.title)}</strong><span>${esc(s.purpose)}</span></a>`).join('')}</nav><p class="tiny">${esc(c.basis)}${c.order_differs?' Your planning order differs from the selected manuscript order.':''}</p><a href="#paper/read-${n.section}">Read selected manuscript in its current order</a></details></section>`;
}

// Compact orientation remains available in every writing step, including Focus.
export function neighbourContextHTML(c,esc){
 const card=(item,label)=>item?`<article><small>${label} · ${esc(item.id)}</small><a href="#paper/${encodeURIComponent(item.id)}">${esc(item.title)}</a><p>${esc(item.plan.contribution||item.purpose)}</p>${item.selected_text?`<details><summary>Read selected manuscript text</summary><p class="tiny">Selected for WISE · read only here</p><p class="prose">${esc(item.selected_text)}</p></details>`:'<p class="tiny">No manuscript text selected yet; this describes the argument’s purpose.</p>'}</article>`:`<article><small>${label}</small><p>${label==='Before'?'Start of the argument. No preceding paragraph.':'End of the argument. No following paragraph.'}</p></article>`;
 return `<section class="wise-neighbour-context" aria-label="Before and after this paragraph">${card(c.before,'Before')}<div class="wise-neighbour-here"><small>This argument · ${esc(c.current.id)}</small><strong>${esc(c.current.purpose)}</strong><a href="#paper/flow-${encodeURIComponent(c.current.id)}">Open whole argument</a></div>${card(c.after,'After')}</section>${c.order_differs?'<p class="tiny">This shows your planning order, which differs from the selected manuscript order.</p>':''}`;
}
